function render(options) {
  const { ctx, width: W, height: H, localT, dur, beatPulse, currentBeat, scene } = options;

  const clamp = (v, min, max) => Math.min(Math.max(v, min), max);
  const easeOutCubic = (t) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
  const windowEase = (time, t0, t1, easing = easeOutCubic) => {
    if (t1 <= t0) return time >= t1 ? 1 : 0;
    return easing(clamp((time - t0) / (t1 - t0), 0, 1));
  };

  const safeDur = Math.max(0.1, dur);
  const p = clamp(localT / safeDur, 0, 1);
  const t = p * 2.7;
  const pulse = Number.isFinite(beatPulse) ? clamp(beatPulse, 0, 1) : 0;

  const cx = W * 0.5;
  const cy = H * 0.5;
  const lineSpacing = Math.round(H * 0.075);

  const primaryColor = '#FFFFFF';
  const accentColor = '#E9135A';

  let line1 = 'ARE';
  let line2 = 'YOU';
  let line3 = 'READY?';

  if (scene && scene.lyricPrimary) {
    const pWords = scene.lyricPrimary.trim().split(/\s+/).filter(Boolean);
    if (pWords.length >= 3) {
      line1 = pWords[0];
      line2 = pWords[1];
      line3 = pWords.slice(2).join(' ');
    } else if (pWords.length === 1) {
      line1 = pWords[0];
    } else if (pWords.length === 2) {
      line1 = pWords[0];
      line2 = pWords[1];
    }
  }

  if (scene && scene.lyricSecondary) {
    const sWords = scene.lyricSecondary.trim().split(/\s+/).filter(Boolean);
    if (sWords.length === 1) {
      line3 = sWords[0];
    } else if (sWords.length >= 2) {
      line2 = sWords[0];
      line3 = sWords.slice(1).join(' ');
    }
  }

  ctx.save();
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, W, H);

  function drawText(text, x, y, color, scaleBounce) {
    ctx.save();
    ctx.translate(x, y);
    if (scaleBounce && scaleBounce !== 1.0) {
      ctx.scale(scaleBounce, scaleBounce);
    }
    const fontSize = Math.round(W * 0.12);
    ctx.font = '900 ' + fontSize + 'px Impact, Arial Black, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(text, 0, 0);

    ctx.fillStyle = '#000000';
    const textW = (ctx.measureText && ctx.measureText(text).width) || fontSize * text.length * 0.6;
    let seed = 1337 + text.length * 17;
    const rand = () => {
      seed = (seed * 1664525 + 1013904223) % 4294967296;
      return seed / 4294967296;
    };
    const flecks = Math.round(text.length * 7);
    for (let i = 0; i < flecks; i++) {
      const fx = -textW * 0.45 + rand() * textW * 0.9;
      const fy = -fontSize * 0.4 + rand() * fontSize * 0.8;
      ctx.fillRect(fx, fy, 2 + rand() * 3, 1.5 + rand() * 2);
    }
    ctx.restore();
  }

  if (t < 0.8) {
    const bounce = 1.0 + windowEase(t, 0.0, 0.25, easeOutCubic) * 0.12 * (1 - t / 0.8) + pulse * 0.05;
    drawText(line1, cx, cy, primaryColor, bounce);
  } else {
    const bounce = 1.0 + windowEase(t, 0.8, 1.05, easeOutCubic) * 0.08 * (1 - (t - 0.8) / 1.9) + pulse * 0.04;
    drawText(line1, cx, cy - lineSpacing, primaryColor, bounce);
    drawText(line2, cx, cy, accentColor, bounce);
    drawText(line3, cx, cy + lineSpacing, primaryColor, bounce);
  }

  ctx.restore();
}

function render(options) {
  const { ctx, width: W, height: H, localT, dur, beatPulse, currentBeat, scene } = options;

  const clamp = (v, min, max) => Math.min(Math.max(v, min), max);
  const easeOutCubic = (t) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
  const windowEase = (time, t0, t1, easing = easeOutCubic) => {
    if (t1 <= t0) return time >= t1 ? 1 : 0;
    return easing(clamp((time - t0) / (t1 - t0), 0, 1));
  };

  const safeDur = Math.max(0.1, dur);
  const p = clamp(localT / safeDur, 0, 1);
  const t = p * 3.9;
  const pulse = Number.isFinite(beatPulse) ? clamp(beatPulse, 0, 1) : 0;

  const cx = W * 0.5;
  const cy = H * 0.5;
  const lineSpacing = Math.round(H * 0.075);

  const primaryColor = '#FFFFFF';
  const accentColor = '#E9135A';

  let heroWord = 'SOMETHING';
  let topWord = 'FOR';
  let botWord = 'BIG';

  if (scene && scene.lyricPrimary) {
    heroWord = scene.lyricPrimary.trim();
  }
  if (scene && scene.lyricSecondary) {
    const sWords = scene.lyricSecondary.trim().split(/\s+/).filter(Boolean);
    if (sWords.length === 1) {
      topWord = sWords[0];
    } else if (sWords.length >= 2) {
      topWord = sWords[0];
      botWord = sWords[1];
    }
  }

  ctx.save();
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, W, H);

  function drawText(text, x, y, opts) {
    opts = opts || {};
    const fontSize = opts.fontSize || Math.round(W * 0.12);
    const fontFamily = opts.fontFamily || 'Impact, Arial Black, sans-serif';
    const fontWeight = opts.fontWeight || '900';
    const color = opts.color || primaryColor;
    const condensed = opts.condensed || false;
    const scaleBounce = opts.scaleBounce || 1.0;

    ctx.save();
    ctx.translate(x, y);
    if (condensed) {
      ctx.scale(0.68 * scaleBounce, 1.15 * scaleBounce);
    } else if (scaleBounce !== 1.0) {
      ctx.scale(scaleBounce, scaleBounce);
    }

    ctx.font = fontWeight + ' ' + fontSize + 'px ' + fontFamily;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(text, 0, 0);

    if (opts.distressed !== false) {
      ctx.fillStyle = '#000000';
      const textW = (ctx.measureText && ctx.measureText(text).width) || fontSize * text.length * 0.6;
      let seed = 2048 + text.length * 13;
      const rand = () => {
        seed = (seed * 1664525 + 1013904223) % 4294967296;
        return seed / 4294967296;
      };
      const flecks = Math.round(text.length * 7);
      for (let i = 0; i < flecks; i++) {
        const fx = -textW * 0.45 + rand() * textW * 0.9;
        const fy = -fontSize * 0.4 + rand() * fontSize * 0.8;
        ctx.fillRect(fx, fy, 2 + rand() * 3, 1.5 + rand() * 2);
      }
    }
    ctx.restore();
  }

  if (t < 0.6) {
    drawText(topWord, cx, cy - lineSpacing * 0.9, { color: accentColor });
    drawText(heroWord, cx, cy + lineSpacing * 0.15, {
      fontSize: Math.round(W * 0.14),
      fontFamily: 'Arial Narrow, sans-serif',
      fontWeight: '700',
      color: primaryColor,
      condensed: true,
      distressed: false,
    });
  } else if (t < 2.0) {
    const bounce = 1.0 + windowEase(t, 0.6, 0.85, easeOutCubic) * 0.08 + pulse * 0.05;
    drawText(topWord, cx, cy - lineSpacing, { color: accentColor, scaleBounce: bounce });
    drawText(heroWord, cx, cy, { color: primaryColor, scaleBounce: bounce });
    drawText(botWord, cx, cy + lineSpacing, { color: accentColor, scaleBounce: bounce });
  } else if (t < 2.9) {
    drawText(heroWord, cx, cy, { color: primaryColor });
    drawText(botWord, cx, cy + lineSpacing, { color: accentColor });
  } else {
    drawText(heroWord, cx, cy, { color: primaryColor });
  }

  ctx.restore();
}

function render(options) {
  const { ctx, width: W, height: H, localT, dur, beatPulse, currentBeat, scene } = options;

  const clamp = (v, min, max) => Math.min(Math.max(v, min), max);

  const safeDur = Math.max(0.1, dur);
  const p = clamp(localT / safeDur, 0, 1);
  const t = p * 4.5;

  const cx = W * 0.5;
  const cy = H * 0.5;

  const primaryColor = '#FFFFFF';
  const accentColor = '#E9135A';
  const beamCoreColor = '#DDD4C6';
  const beamEdgeColor = '#1C2926';

  let brandName = 'Soboraa';
  let headerText = 'COMING SOON';
  let subText = 'STAY TUNED';

  if (scene && scene.lyricPrimary) {
    brandName = scene.lyricPrimary.trim();
  }
  if (scene && scene.lyricSecondary) {
    const sParts = scene.lyricSecondary.includes('/')
      ? scene.lyricSecondary.split('/').map(s => s.trim()).filter(Boolean)
      : scene.lyricSecondary.split(/\s{2,}/).map(s => s.trim()).filter(Boolean);
    if (sParts.length >= 2) {
      headerText = sParts[0];
      subText = sParts[1];
    } else {
      headerText = scene.lyricSecondary.trim();
    }
  }

  ctx.save();
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, W, H);

  // 1. Diagonal metallic spotlight beam
  ctx.save();
  const sweepCycle = Math.sin(t * 1.85 + 0.8);
  const offset = sweepCycle * (W * 0.42);

  ctx.translate(cx + offset, cy + offset * 0.65);
  ctx.rotate((-38 * Math.PI) / 180);

  const beamHalfWidth = W * 0.52;
  const grad = ctx.createLinearGradient(0, -beamHalfWidth, 0, beamHalfWidth);
  grad.addColorStop(0.0, '#000000');
  grad.addColorStop(0.22, beamEdgeColor);
  grad.addColorStop(0.46, beamCoreColor);
  grad.addColorStop(0.5, '#FFFDF9');
  grad.addColorStop(0.54, beamCoreColor);
  grad.addColorStop(0.78, beamEdgeColor);
  grad.addColorStop(1.0, '#000000');

  ctx.fillStyle = grad;
  ctx.fillRect(-W * 2, -beamHalfWidth, W * 4, beamHalfWidth * 2);
  ctx.restore();

  // 2. Centered Dark Serif Brand Silhouette
  ctx.save();
  ctx.font = '700 ' + Math.round(W * 0.17) + 'px Georgia, Times New Roman, serif';
  ctx.fillStyle = '#050505';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowColor = 'rgba(255, 255, 255, 0.18)';
  ctx.shadowBlur = 12;
  ctx.fillText(brandName, cx, cy + Math.round(H * 0.02));
  ctx.restore();

  // 3. Top Header: Outlined white first (0 to 1.1s), then solid magenta (1.1s+)
  const isOutlinedPhase = t < 1.1;
  ctx.save();
  ctx.font = '900 ' + Math.round(W * 0.088) + 'px Impact, Arial Black, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  if (isOutlinedPhase) {
    ctx.strokeStyle = primaryColor;
    ctx.lineWidth = Math.max(2, Math.round(W * 0.005));
    ctx.strokeText(headerText, cx, Math.round(H * 0.20));
  } else {
    ctx.fillStyle = accentColor;
    ctx.fillText(headerText, cx, Math.round(H * 0.20));
  }
  ctx.restore();

  // 4. Subheader: Pops in at t >= 2.1s
  if (t >= 2.1) {
    const isCondensedFlash = t < 2.8;
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = primaryColor;
    if (isCondensedFlash) {
      ctx.translate(cx, Math.round(H * 0.275));
      ctx.scale(0.68, 1.15);
      ctx.font = '600 ' + Math.round(W * 0.076) + 'px Arial Narrow, sans-serif';
      ctx.fillText(subText, 0, 0);
    } else {
      ctx.font = '900 ' + Math.round(W * 0.062) + 'px Impact, Arial Black, sans-serif';
      ctx.fillText(subText, cx, Math.round(H * 0.275));
    }
    ctx.restore();
  }

  ctx.restore();
}
